import type { BufferGeometry } from 'three';

export const ELECTRIC_MATERIAL_ROLES = ['paint', 'maple', 'fretboard', 'nickel', 'dark', 'inlay'] as const;
type MaterialRole = typeof ELECTRIC_MATERIAL_ROLES[number];
type Point = [number, number, number];
interface Bounds { min: Point; max: Point }
interface FinishGroup { start: number; count: number; materialIndex: number }

/** Classify the fixed recovered mesh without welding, reordering or editing its buffers. */
export function electricFinishGroups(geometry: BufferGeometry): FinishGroup[] {
  const position = geometry.getAttribute('position'), index = geometry.getIndex();
  if (!position || !index || index.count % 3) throw new Error('The electric finish needs the recovered indexed geometry.');
  const points: Point[] = Array.from({ length: position.count }, (_, i) => [position.getX(i), position.getY(i), position.getZ(i)]);
  const parents = Int32Array.from({ length: position.count }, (_, i) => i);
  const root = (vertex: number): number => {
    while (parents[vertex] !== vertex) { parents[vertex] = parents[parents[vertex]]; vertex = parents[vertex]; }
    return vertex;
  };
  const join = (a: number, b: number) => {
    a = root(a); b = root(b);
    if (a !== b) parents[Math.max(a, b)] = Math.min(a, b);
  };
  // Attribute seams split source indices; positional connectivity is only an analysis mask.
  const seams = new Map<string, number>();
  points.forEach((point, i) => {
    const key = point.map(value => Math.round(value * 1e6)).join(',');
    const other = seams.get(key);
    if (other === undefined) seams.set(key, i);
    else join(i, other);
  });
  for (let i = 0; i < index.count; i += 3) {
    join(index.getX(i), index.getX(i + 1)); join(index.getX(i), index.getX(i + 2));
  }
  const components = new Map<number, Bounds>();
  for (let i = 0; i < index.count; i++) {
    const vertex = index.getX(i), id = root(vertex), point = points[vertex];
    let bounds = components.get(id);
    if (!bounds) { bounds = { min: [...point], max: [...point] }; components.set(id, bounds); }
    for (let axis = 0; axis < 3; axis++) {
      bounds.min[axis] = Math.min(bounds.min[axis], point[axis]);
      bounds.max[axis] = Math.max(bounds.max[axis], point[axis]);
    }
  }
  const material = (bounds: Bounds, center: Point): MaterialRole => {
    const size = bounds.max.map((value, axis) => value - bounds.min[axis]);
    const x = (bounds.min[0] + bounds.max[0]) / 2, z = (bounds.min[2] + bounds.max[2]) / 2;
    if (size[0] > 1) {
      // Body, neck and headstock share connectivity. Keep the cutaway horns painted.
      const neckWidth = .023 + .009 * Math.max(0, Math.min(1, (center[0] + .715) / .528));
      return center[0] < -.718 || (center[0] < -.187 && Math.abs(center[2]) < neckWidth) ? 'maple' : 'paint';
    }
    if (size[0] > .5 && size[2] > .04 && size[1] < .01) return 'fretboard';
    if (x > -.64 && x < -.19 && size[0] < .014 && size[2] < .025 && size[1] < .001) return 'inlay';
    if (x > -.205 && x < -.055 && size[0] > .03 && size[2] > .06) return 'dark';
    if (x > -.72 && x < -.70 && size[2] > .04) return 'dark';
    if (x > -.02 && x < .05 && z > .06 && size[0] < .026 && size[2] < .026) return 'dark';
    return 'nickel';
  };
  const groups: FinishGroup[] = [];
  for (let start = 0; start < index.count; start += 3) {
    const a = index.getX(start), b = index.getX(start + 1), c = index.getX(start + 2);
    const center: Point = [0, 1, 2].map(axis => (points[a][axis] + points[b][axis] + points[c][axis]) / 3) as Point;
    const materialIndex = ELECTRIC_MATERIAL_ROLES.indexOf(material(components.get(root(a))!, center));
    const previous = groups[groups.length - 1];
    if (previous?.materialIndex === materialIndex) previous.count += 3;
    else groups.push({ start, count: 3, materialIndex });
  }
  if (new Set(groups.map(group => group.materialIndex)).size !== ELECTRIC_MATERIAL_ROLES.length) {
    throw new Error('The recovered electric guitar could not be separated into its finish regions.');
  }
  return groups;
}
